message.content:
{"diagnosis": "Loopback send 0xa5 was latched as 0x00 in recv_buf_data, causing TRAP uart data mismatch got 0x00 want 0xa5. The default-state shift uses {ser_rx, recv_pattern[7:0]} which is 9 bits and truncates to the old recv_pattern, so ser_rx is never shifted in. Thus recv_pattern stays at reset and state 10 copies 0x00 to recv_buf_data.", "patch_diff": "diff --git a/picosoc/simpleuart.v b/picosoc/simpleuart.v
--- a/picosoc/simpleuart.v
+++ b/picosoc/simpleuart.v
@@ -96,7 +96,7 @@
 				default: begin
 					if (recv_divcnt > cfg_divider) begin
-						recv_pattern <= {ser_rx, recv_pattern[7:0]};
+						recv_pattern <= {ser_rx, recv_pattern[7:1]};
 						recv_state <= recv_state + 1;
 						recv_divcnt <= 0;
 					end
 				end
", "expected": "tohost PASS 0x1, loopback got 0xa5 want 0xa5 with no TRAP"}

